const assert=require('node:assert/strict');
const R=require('./chapter3-state'),V=require('./chapter3-view');
const send=(s,type,target,value)=>R.act(s,{type,target,value});
const set=(s,k,v)=>send(s,'set',k,v);
const observe=s=>send(send(s,'run'),'observed');
let s=send(R.initial(),'enter','insulation');
assert.equal(observe(s).step,'setup','prediction is required, but not exact degrees');
s=set(set(s,'material','cloth'),'compare','higher');s=observe(s);
assert.equal(s.work.insulation.actual,17);
s=set(s,'explanation','out');assert.equal(send(s,'check').done.insulation,undefined);
s=R.initial(JSON.parse(JSON.stringify(s)));s=set(s,'explanation','in');
assert.equal(send(s,'check').done.insulation,true,'wrong initial prediction must not block valid observation');
s=send(R.initial(),'enter','radiation');s=set(s,'prediction','same');s=observe(s);
s=set(s,'shield',true);assert.equal(s.step,'setup');assert.equal(s.observations.radiation,undefined,'changed setup must not retain stale result');
s=R.initial(JSON.parse(JSON.stringify(s)));assert.equal(s.step,'setup');
s=observe(s);s=set(s,'explanation','light');assert.equal(send(s,'check').done.radiation,true);
const picture=V.illustration('radiation',s.work.radiation,'result');
assert.match(picture,/금속판 \+ 온도 센서/);
assert.match(V.illustration('insulation',R.initial().work.insulation,'setup'),/냉찜질 팩/);
console.log('chapter3 inquiry: goals, compare, wrong prediction recovery, stale result reset PASS');
